{
  "lecture": [
    {
      "etiquette": "F40",
      "R1": {
        "valeur": 1,
        "passage": "À dollars égaux, la part des composantes conditionnelles couvertes par les retenues après 2 générations passe d'au plus 10 % pour le témoin à au moins 30 % pour le bras tableau croisé."
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle lu une fois : composantes conditionnelles et non conditionnelles couvertes, aux trois étages ; lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "Le tableau n'est ni un verdict, ni l'oracle, ni la loi plantée, ni un score de juge ou de moniteur : ce sont des effectifs bruts d'épisodes publics."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "Chaque trait continu est coupé à sa médiane sur cet échantillon. Pour chaque paire non ordonnée de traits, le tableau donne les effectifs et la fréquence de chaque issue dans les quatre cases."
      },
      "R6": {
        "valeur": 1,
        "passage": "Bon marché d'abord : un modèle peu cher, 20 mondes, 3 bras (témoin, croisé, placebo), 2 générations, environ 400 appels, soit des dizaines de dollars."
      },
      "R7": {
        "valeur": 1,
        "passage": "Elle laisse en revanche une pente de signe opposé dans les deux branches d'un croisement à deux traits. Un proposeur qui voit ce croisement peut la proposer avant même que sa condition soit archivée."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F41",
      "R1": {
        "valeur": 1,
        "passage": "au moins 15 % de cartes en moins qui ne font que recopier l'existant, et au moins autant de composantes plantées couvertes, à coût égal"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes (oracle) et copies promues ; témoin à coût égal : même génération sans filtre"
      },
      "R3": {
        "valeur": 0,
        "motif": "La fiche introduit une auto-évaluation de nouveauté et un filtre à modèle avec accès au Web qui sélectionne les cartes, sans nommer ni justifier la réouverture des objections correspondantes."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 0,
        "motif": "La notion de cartes trop proches de travaux existants n'est assortie d'aucune procédure ou règle de décision permettant de programmer le filtre tel quel."
      },
      "R6": {
        "valeur": 0,
        "motif": "Un témoin à coût égal est nommé, mais le coût indiqué par génération ne borne pas l'expérience décisive, dont le nombre de générations n'est pas fixé."
      },
      "R7": {
        "valeur": 0,
        "motif": "Écarter les ressemblances bibliographiques n'implique ni moins de copies au sens de l'oracle ni une couverture préservée, puisque le filtre peut aussi retirer des composantes vraies."
      },
      "N": {
        "valeur": "C3",
        "passage_fiche": "Après la génération, un modèle relié à un moteur de recherche bibliographique et au Web écarte toute carte trop semblable à des travaux existants.",
        "passage_catalogue": "**filtre de nouveauté** : un modèle relié à une recherche bibliographique (Semantic Scholar) et au Web écarte les idées trop proches de l'existant"
      }
    },
    {
      "etiquette": "F42",
      "R1": {
        "valeur": 1,
        "passage": "la médiane sur les 15 mondes du nombre de composantes distinctes couvertes à l'étage des propositions brutes est supérieure d'au moins 1 dans le bras à constats"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : composantes certifiées couvertes, étages des propositions brutes, des représentants et des retenues ; lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "Aucun modèle ne note, ne trie, ni ne filtre les constats. Extraction, gardien, regroupement des doublons, juge inchangés."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "appels 2 à 7 (sessions neuves, sans historique) = vue habituelle complète + un seul constat (le i-ème, dans l'ordre rendu, sans tri) + consigne d'une carte au gabarit ; réponse brute scellée."
      },
      "R6": {
        "valeur": 1,
        "passage": "15 mondes × 4 proposeurs × (7 appels courts + K appels témoin) en génération 1 ; ordre de quelques dizaines de dollars, devis avant feu vert."
      },
      "R7": {
        "valeur": 1,
        "passage": "Le passage par une liste de constats déclarés, puis l'isolement de chacun dans une session qui ne voit pas les autres, supprime la pression de cohérence interne d'un appel unique"
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F43",
      "R1": {
        "valeur": 1,
        "passage": "À dollars totaux égaux : composantes de profondeur 1 et 2 couvertes aux retenues : au moins +2 sur la somme des 10 mondes pour le bras testé"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : composantes certifiées couvertes par profondeur (surface, 1, 2), à chaque génération et aux retenues finales ; lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "arrêt par plafond, jamais par verdict du juge ; (4) juge, gardien, regroupement, archive inchangés ; aucun score ni coût servi aux proposeurs."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 1,
        "passage": "génération 1 servie par les seuls instruments locaux (mêmes vue, grammaire, six cartes, session neuve, réponse brute scellée) ; générations 2 et suivantes servies par les proposeurs de frontière habituels"
      },
      "R6": {
        "valeur": 1,
        "passage": "10 mondes × 2 bras × 3 à 4 générations × 4 proposeurs ; ordre d'une centaine de dollars pour la frontière, calcul local en sus ; devis avant feu vert."
      },
      "R7": {
        "valeur": 0,
        "motif": "Le mécanisme suppose sans l'établir que les instruments locaux trouvent les conditions de surface et que remplacer une génération de frontière finance une génération entière supplémentaire, alors que leur coût positif peut empêcher cette dernière et inverser le gain."
      },
      "N": {
        "valeur": "aucune"
      }
    }
  ]
}
